/**
 * catalog.js — loads and indexes the two static data files.
 *
 * Both are plain JSON assets. `exercises.json` is generated by
 * `tools/build_catalog.py`; `routines.json` is hand-written.
 */

/** Range shown to the user, in minutes. Clamped by product decision. */
export const MIN_MINUTES = 5;
export const MAX_MINUTES = 15;

let cache = null;

export async function loadCatalog() {
  if (cache) return cache;

  // Relative paths — the site is served from /Omnia/, not the domain root.
  const [exercisesRes, routinesRes] = await Promise.all([
    fetch('assets/data/exercises.json'),
    fetch('assets/data/routines.json'),
  ]);

  if (!exercisesRes.ok || !routinesRes.ok) {
    throw new Error('Could not load the exercise catalog.');
  }

  const exerciseDoc = await exercisesRes.json();
  const routineDoc = await routinesRes.json();

  const byId = new Map(exerciseDoc.exercises.map((e) => [e.id, e]));

  const routines = routineDoc.routines.map((routine) => {
    // Drop unknown ids rather than rendering a hole. `--check` in the build
    // script catches these before they ship, so this is belt and braces.
    const exercises = routine.exercises
      .map((id) => byId.get(id))
      .filter(Boolean);

    return { ...routine, exercises, duration: estimateRange(exercises.length) };
  });

  cache = { exercises: exerciseDoc.exercises, byId, routines };
  return cache;
}

export function getRoutine(routines, id) {
  return routines.find((r) => r.id === id) || null;
}

/**
 * The duration range for a routine, in whole minutes.
 *
 * A range rather than a number for two reasons, both real: routines hold
 * different numbers of exercises, and the user picks 30s or 45s before
 * starting. Clamped to 5–15 because that is the promise Omnia makes — a
 * routine is never a two-minute token effort or a half-hour session.
 */
export function estimateRange(exerciseCount) {
  const clamp = (mins) =>
    Math.min(MAX_MINUTES, Math.max(MIN_MINUTES, Math.round(mins)));
  return {
    low: clamp((exerciseCount * 30) / 60),
    high: clamp((exerciseCount * 45) / 60),
  };
}

/** The single duration a routine will actually take, given the chosen interval. */
export function estimateMinutes(exerciseCount, intervalSeconds) {
  return Math.max(1, Math.round((exerciseCount * intervalSeconds) / 60));
}
